/*
 * prog56_kruskal_mst – reconstructed from the supplied binary.
 *
 * Behaviour (as observed from the original program):
 *   1. The program expects exactly one command‑line argument: the number of
 *      vertices (a positive decimal integer).  If the argument is missing,
 *      not a pure decimal number, or ≤ 0, the program prints
 *
 *          INVALID_ARGS
 *
 *      and exits.
 *
 *   2. Afterwards it reads an arbitrary number of edges from standard input.
 *      Each line must contain three integers:  u v w
 *
 *          u – first vertex (0‑based)
 *          v – second vertex (0‑based)
 *          w – weight of the edge (any signed integer)
 *
 *      Lines that cannot be parsed are ignored; reading stops at EOF.
 *
 *   3. The program runs Kruskal's algorithm to compute a Minimum Spanning
 *      Tree (MST).  The union‑find structure is initialised for the given
 *      number of vertices.
 *
 *   4. If the graph is disconnected (i.e. the MST does not contain
 *      `vertices‑1` edges) the program prints
 *
 *          DISCONNECTED
 *
 *      and exits.
 *
 *   5. Otherwise it prints the total weight of the MST and the list of
 *      edges that belong to the MST, in the order they were selected by
 *      Kruskal.  The format matches the original binary exactly:
 *
 *          weight=%d edges=,u1-v1,u2-v2,...\n
 *      (a leading comma before the first edge, commas between edges, and a
 *      final newline.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

typedef struct {
    int u, v;
    int w;
} Edge;

/* ---------- Union‑Find (Disjoint Set) ---------- */
static int *uf_parent = NULL;

static void uf_init(int n)
{
    uf_parent = malloc(n * sizeof(int));
    for (int i = 0; i < n; ++i)
        uf_parent[i] = i;
}

static int uf_find(int x)
{
    if (uf_parent[x] != x)
        uf_parent[x] = uf_find(uf_parent[x]);
    return uf_parent[x];
}

static void uf_union(int a, int b)
{
    int ra = uf_find(a);
    int rb = uf_find(b);
    if (ra != rb)
        uf_parent[ra] = rb;
}

/* ---------- Helper: check that a string is a pure decimal integer ---------- */
static int is_decimal_integer(const char *s)
{
    if (*s == '\0')
        return 0;
    while (*s) {
        if (!isdigit((unsigned char)*s))
            return 0;
        ++s;
    }
    return 1;
}

/* ---------- Comparison function for qsort (ascending weight) ---------- */
static int cmp_edge(const void *a, const void *b)
{
    const Edge *ea = (const Edge *)a;
    const Edge *eb = (const Edge *)b;
    if (ea->w < eb->w) return -1;
    if (ea->w > eb->w) return 1;
    return 0;
}

int main(int argc, char *argv[])
{
    /* ----- argument validation ----- */
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    if (!is_decimal_integer(argv[1])) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long <= 0) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;   /* number of vertices */

    /* ----- read edges from stdin ----- */
    Edge *edges = NULL;
    size_t cap = 0, cnt = 0;
    while (1) {
        int u, v, w;
        int rc = scanf("%d %d %d", &u, &v, &w);
        if (rc == EOF || rc < 3)
            break;          /* stop on EOF or malformed line */
        if (cnt == cap) {
            cap = cap ? cap * 2 : 16;
            edges = realloc(edges, cap * sizeof(Edge));
        }
        edges[cnt++] = (Edge){u, v, w};
    }

    /* ----- trivial case: single vertex ----- */
    if (n == 1) {
        printf("weight=0 edges=\n");
        free(edges);
        return 0;
    }

    /* ----- Kruskal's algorithm ----- */
    uf_init(n);
    qsort(edges, cnt, sizeof(Edge), cmp_edge);

    Edge *mst = malloc((n - 1) * sizeof(Edge));
    int mst_cnt = 0;
    long total_weight = 0;

    for (size_t i = 0; i < cnt && mst_cnt < n - 1; ++i) {
        int ru = uf_find(edges[i].u);
        int rv = uf_find(edges[i].v);
        if (ru != rv) {
            uf_union(ru, rv);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }

    free(edges);
    free(uf_parent);

    if (mst_cnt != n - 1) {
        puts("DISCONNECTED");
        free(mst);
        return 0;
    }

    /* ----- output in the exact format of the original binary ----- */
    printf("weight=%ld edges=", total_weight);
    for (int i = 0; i < mst_cnt; ++i) {
        putchar(',');
        printf("%d-%d", mst[i].u, mst[i].v);
    }
    putchar('\n');

    free(mst);
    return 0;
}
